var t=`0742-injera`;var n=`world-0742`;var r=`ET`;var a=`eastern-africa`;var o=8;var s=2931;var l={en:`Injera`,ua:`Інжера`};var d={en:`Injera is a Ethiopia classic prepared with teff flour, injera starter. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Injera made from teff flour with the cataloged injera starter and long active fermentation; sourness depends on starter activity.`,ua:`Інжера, страва кухні країни Ефіопія зі складниками: борошно тефу, закваска для інджери. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Інжера з борошна тефу й закваски з каталогу після тривалого активного бродіння; кислинка залежить від сили закваски.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`teff-flour`,430,`g`],[`water`,670,`ml`],[`injera-starter`,80,`g`]]},{en:`Ferment the teff batter with the injera starter in a covered nonreactive vessel for roughly 48 hours, until distinctly bubbly and pleasantly sour. Discard if spoiled.`,ua:`Залиште тісто з тефу й закваски в накритій неактивній посудині приблизно на 48 годин до виразних бульбашок і приємної кислинки. За ознак псування утилізуйте.`,t:[`injera-fermentation`],m:2880,i:[]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`water`,250,`ml`],[`table-salt`,5,`g`]]},{en:`Swirl a very thin layer of sour batter on a hot nonstick griddle; cover and cook ONLY from below until the porous top is dry, without flipping.`,ua:`Розподіліть дуже тонкий шар кислого тіста на гарячій антипригарній сковороді; накрийте й готуйте ЛИШЕ знизу до сухого пористого верху, не перевертаючи.`,t:[`injera-griddle-baking`],m:28,i:[[`sunflower-oil`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var g={slug:t,id:n,country:`ET`,region:a,servings:8,minutes:s,title:l,text:d,steps:u};export{r as country,g as default,n as id,s as minutes,a as region,o as servings,t as slug,u as steps,d as text,l as title};